/**
 * Places (visionOS-style Environments), pure and unit-tested.
 *
 * Default: your own room (mixed reality, passthrough). Three calm evening
 * places can replace the far view; by default the lower part of the view
 * (your real table, your hands) stays passthrough ("Table stays"), or the
 * place surrounds you completely ("Full").
 *
 * Panoramas (v5): AI-generated by Astra (the studio's image agent) from our briefs,
 * upscaled ×4 locally with Real-ESRGAN, seam and poles fixed, KTX2 / Basis ETC1S
 * 6144 × 2048 equal-area, lazy-loaded only when chosen (JPG equirectangular
 * fallback). Provenance and licences: TECH.md §14.
 */

export type PlaceId =
  | 'room'
  // Night places (19 Oct 2026): Astra panoramas (meta-vr/concept/panoramas-nuit), each with its living layer
  // (src/desk/living/, logic/living.ts). The dusk places of v5–v8 are archived (archive/environments-dusk/).
  | 'ember-fire'
  | 'moon-lake'
  | 'moon-beach'
  | 'northern-lights'
  | 'rain-veranda'
  | 'firefly-meadow'
  | 'desert-stars'
  | 'fireside-cabin'
  | 'rooftop-city';
export const PLACE_IDS: readonly PlaceId[] = [
  'room',
  'ember-fire',
  'moon-lake',
  'moon-beach',
  'northern-lights',
  'rain-veranda',
  'firefly-meadow',
  'desert-stars',
  'fireside-cabin',
  'rooftop-city',
];

/** The Places menu: your room + the nine night places, in this order (coordinator, 19 Oct 2026). */
export const MENU_PLACES: readonly PlaceId[] = PLACE_IDS;

export type Immersion = 'table' | 'full';

export interface PlaceGrade {
  /** Linear exposure multiplier. */
  exposure: number;
  /** Colour balance (multiplies linear colour). */
  tint: [number, number, number];
  saturation: number;
  /** Day-for-night: bright, cool sky regions sink toward deep blue (0..1). */
  night: number;
  /** Procedural rain streaks (0..1). */
  rain: number;
  /** Procedural stars added in the dark sky (0..1). */
  stars: number;
  /** Mip bias: slight defocus, like a distant view. */
  blur: number;
  /** How much the evening darkens this place, 0..1 (default 1); night panoramas ≈ 0.35 (environment.ts). */
  evening?: number;
  /**
   * How dark the ground near you sinks, 0..1 (default 0.22: the dusk photos, eye to the horizon). Night places whose
   * life is on the ground (surf, a campfire, a meadow) keep more of it (19 Oct: the beach's surf was nearly black).
   */
  ground?: number;
}

/** The evening light rig for this place (key = the warm lamp light on the desk; fill = the place). */
export interface PlaceLight {
  key: [number, number, number];
  fillSky: [number, number, number];
  fillGround: [number, number, number];
}

/**
 * v8: in-engine rain of a place (world-anchored, around the seat). Distances in metres, measured on the
 * floor from the point under your eyes; yaw 0 = what you face when seated, positive = to your right.
 * You sit sheltered under a roof: no drop ever falls inside it.
 */
export interface RainSpec {
  /** Drops per layer (near ≤ 4 m, mid ≤ 10 m, far ≤ 24 m): the budget. */
  drops: [number, number, number];
  /** Roof edge: distance straight ahead, and to the sides (an ellipse around the seat). */
  roofFront: number;
  roofSide: number;
  /** Eave height above the floor (drips fall from here). */
  eave: number;
  /** The garden opens between these yaws (degrees); behind you is the house. */
  open: [number, number];
  /** Wind: drift direction (yaw, degrees) and slant (metres of drift per metre of fall). */
  windYaw: number;
  slant: number;
  /** Pond in the panorama (ripples): centre (yaw°, distance), half-size across / along the view, depth below the floor. */
  pond: { yaw: number; dist: number; across: number; along: number; drop: number };
}

export interface Place {
  id: PlaceId;
  name: string;
  /** Short line for the caption when you arrive. */
  arrive: string;
  /** KTX2 panorama (equal-area layout), lazy-loaded. */
  photo: string | null;
  /**
   * 26 Oct (HD places): the same panorama upscaled ×4 (DAT2) to 8192 × 2732, UASTC → ASTC 4×4 / BC7 / ETC2 on the GPU
   * (21.3 MiB, 8–10 MB to download). Loaded only in calm moments and only if the GPU takes 8192-wide compressed
   * textures; `photo` (6k ETC1S) stays the fast path and the fallback.
   */
  photoHd?: string;
  /** Equirectangular JPG used if the KTX2 path is unavailable. */
  fallback: string | null;
  thumb: string | null;
  /** Which part of the panorama you face when seated: yaw = 2π × (u − 0.5), u in [0, 1] across the photo. */
  yaw: number;
  grade: PlaceGrade;
  light: PlaceLight;
  credit: string;
  /** v8: in-engine rain (garden). */
  rain?: RainSpec;
}

/** The rig of the original evening (your room). Matches materials.ts defaults. */
