export type PlaceCommand =
  | { type: 'place'; place: PlaceId }
  | { type: 'places' }
  | { type: 'immersion'; level: Immersion };

/** Spoken names → a place (coordinator, 19 Oct 2026). Order matters: "fireplace" before "fire", "meadow" here. */
const PLACE_WORDS: Array<{ places: PlaceId[]; pattern: RegExp }> = [
  { places: ['room'], pattern: /\b(my room|the room|my real room|real room|my place|home|passthrough|pass through|reality)\b/u },
  { places: ['fireside-cabin'], pattern: /\b(fireplace|fireside|hearth|chalet|log cabin|cosy cabin|cozy cabin)\b/u },
  { places: ['ember-fire'], pattern: /\b(the fire|a fire|fire|campfire|camp fire|bonfire|embers?|fire pit|clearing)\b/u },
  { places: ['moon-lake'], pattern: /\b(lake|lakeside|the water|mist)\b/u },
  { places: ['moon-beach'], pattern: /\b(beach|cove|sea|ocean|seaside|waves|shore)\b/u },
  { places: ['northern-lights'], pattern: /\b(snow|snowy|cabin|winter|refuge|northern lights|aurora|auroras)\b/u },
  { places: ['rain-veranda'], pattern: /\b(garden|japan|japanese|rain|the rain|veranda|tea house)\b/u },
  { places: ['firefly-meadow'], pattern: /\b(fireflies|firefly|meadow|summer)\b/u },
  { places: ['desert-stars'], pattern: /\b(desert|dunes?|sand|the stars|stars|milky way|sky)\b/u },
  { places: ['rooftop-city'], pattern: /\b(city|rooftop|roof|town|terrace)\b/u },
];

/** The version of a concept the menu shows (else the first listed). */
function preferred(places: PlaceId[]): PlaceId {
  return places.find((id) => MENU_PLACES.includes(id)) ?? places[0];
}

/**
 * 26 Oct (the lamp shows the places): what you can say while a place is shown inside the globe. Whole short
 * sentences only (never "yes" / "not now", which answer the lamp's questions). A place's name still goes straight
 * there (parsePlaceCommand).
 */
export type GlobeCommand = 'next' | 'previous' | 'choose' | 'close';
export function parseGlobeCommand(normalized: string): GlobeCommand | null {
  const n = normalized.trim().replace(/^(please |ok |okay )/u, '').replace(/ please$/u, '');
  if (/^(next( one| place)?|another( one| place)?|show me another( one)?|the next one|and the next)$/u.test(n)) return 'next';
  if (/^(previous( one| place)?|back one|the one before|go back one|the last one|before that)$/u.test(n)) return 'previous';
  if (/^(this one|that one|here|go there|take me there|lets go there|i want this one|choose this one|lets go)$/u.test(n)) return 'choose';
  if (/^(close( it| the places| places)?|never mind|nevermind|stay here|no thanks)$/u.test(n)) return 'close';
  return null;
}

/**
 * Spoken place commands. Anchored to the start of the sentence so that a
 * brain dump that mentions a lake ("call the lake house") never teleports you.
 * `normalized` is lower-case without punctuation (logic/text.ts normalize).
 */
export function parsePlaceCommand(normalized: string): PlaceCommand | null {
  const n = normalized.trim();
  if (/^(places|environments?|change (the )?(place|scene|environment)|where can (i|we) go|show (me )?(the )?places)$/u.test(n)) {
    return { type: 'places' };
  }
  // 29 Oct: the bottom row's capsule says « Mixed | Full »: its two words are commands too.
  if (/^(full|full mode|full immersion|fully immersive|more immersive|all the way|surround me|hide my room)$/u.test(n)) {
    return { type: 'immersion', level: 'full' };
  }
  if (/^(mixed|mixed mode|mixed reality|partial immersion|less immersive|keep my table|show my table|i want to see my table)$/u.test(n)) {
    return { type: 'immersion', level: 'table' };
  }
  if (/^((lets )?(sit|go|stay) by the fire|by the fire|light a fire|campfire)$/u.test(n)) {
    return { type: 'place', place: 'ember-fire' };
  }
  if (/^(back to (my |the )?(room|real room|reality|passthrough)|leave (the )?(lake|garden|beach|fire|city|rooftop|meadow|desert)|my room please|take me (back )?home)\b/u.test(n)) {
    return { type: 'place', place: 'room' };
  }
  const command = /^(take me (to|back to)|go to|bring me to|show me|switch to|lets go to|i want to go to|move to|can we go to|go back to)\s+(.*)$/u.exec(n);
  if (command != null) {
    const rest = command[3];
    for (const { places, pattern } of PLACE_WORDS) {
      if (pattern.test(rest)) {
        return { type: 'place', place: preferred(places) };
      }
    }
  }
  return null;
}

export function isPlaceId(value: unknown): value is PlaceId {
  return typeof value === 'string' && (PLACE_IDS as readonly string[]).includes(value);
}

/** Next place of the menu when cycling (ornament long-press alternative, tests). */
export function nextPlace(current: PlaceId): PlaceId {
  return MENU_PLACES[(MENU_PLACES.indexOf(current) + 1) % MENU_PLACES.length];
}

/** Linear interpolation of two rigs (crossfade between places). */
export function mixLight(a: PlaceLight, b: PlaceLight, t: number): PlaceLight {
  const k = Math.min(1, Math.max(0, t));
  const lerp3 = (x: [number, number, number], y: [number, number, number]): [number, number, number] => [
    x[0] + (y[0] - x[0]) * k,
    x[1] + (y[1] - x[1]) * k,
    x[2] + (y[2] - x[2]) * k,
  ];
  return { key: lerp3(a.key, b.key), fillSky: lerp3(a.fillSky, b.fillSky), fillGround: lerp3(a.fillGround, b.fillGround) };
}

/** What a place's photo looks like as light: mean linear colour of the sky half and the ground half, and overall luminance. */
export interface PlaceMeasure {
  sky: [number, number, number];
  ground: [number, number, number];
  lum: number;
}

/** Mean linear luminance of a dusk place (lake, garden): the level the hand-tuned rigs were made for. */
const REF_LUM = 0.12;

const luminance = (c: readonly [number, number, number]): number => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];

/**
 * The tray takes the light of the place it is in (owner, 19 Oct: "the tray should match each environment"):
 * a dark night place lowers the warm key (the lamp becomes the light), and the fill takes the colour of the
 * place's sky (above) and ground (below). `immersion` 0 = "Table stays" (the real room still lights half), 1 = Full.
 */
export function adaptLight(light: PlaceLight, m: PlaceMeasure | null, immersion = 1): PlaceLight {
  if (m == null) return light;
  // Close to the eye's own response: a place half as bright gives a key about 0.6 as strong; floor 0.22 (the lamp still lights).
  const raw = Math.min(1, Math.max(0.22, (Math.max(0, m.lum) / REF_LUM) ** 0.75));
  const k = 1 - (1 - raw) * (0.5 + 0.5 * Math.min(1, Math.max(0, immersion)));
  const hue = (c: [number, number, number]): [number, number, number] => {
    const l = luminance(c);
    if (l < 1e-5) return [1, 1, 1];
    return c.map((x) => Math.min(1.8, Math.max(0.5, x / l))) as [number, number, number];
  };
  const fill = (hand: [number, number, number], measured: [number, number, number]): [number, number, number] => {
    const h = hue(measured);
    const l = luminance(hand) * (0.55 + 0.45 * k);
    // Half the place's own hue, half the hand-tuned one: a hint of moonlight blue or fire amber, never a cast.
    const base = hue(hand);
    return [0, 1, 2].map((i) => l * (0.5 * base[i] + 0.5 * h[i])) as [number, number, number];
  };
  return {
    key: [light.key[0] * k, light.key[1] * k, light.key[2] * k],
    fillSky: fill(light.fillSky, m.sky),
    fillGround: fill(light.fillGround, m.ground),
  };
}

/** HD panoramas are 8192 wide: the GPU must take that size. */
export const HD_WIDTH = 8192;

/**
 * 26 Oct (HD places): can this GPU show the 8k UASTC panoramas? It needs 8192-wide textures (MAX_TEXTURE_SIZE, not
 * documented by Meta for Quest Browser: read at run time) and a compressed target for UASTC — ASTC (Adreno, Khronos
 * KTX guide), BC7 (desktop) or ETC2. Without one, three's KTX2Loader would decode to raw RGBA: 89 MB per place. No.
 */
export function hdSupport(maxTextureSize: number, has: (ext: string) => boolean): { ok: boolean; why: string } {
  if (maxTextureSize < HD_WIDTH) return { ok: false, why: `MAX_TEXTURE_SIZE ${maxTextureSize} < ${HD_WIDTH}` };
  const target = has('WEBGL_compressed_texture_astc') ? 'ASTC' : has('EXT_texture_compression_bptc') ? 'BC7' : has('WEBGL_compressed_texture_etc') ? 'ETC2' : null;
  if (target == null) return { ok: false, why: 'no ASTC / BC7 / ETC2: UASTC would be decoded uncompressed' };
  return { ok: true, why: `${target}, MAX_TEXTURE_SIZE ${maxTextureSize}` };
}
